"""Build a static, source-linked systemic therapy comparison and reference library."""
from pathlib import Path
from html import escape as esc
import argparse,importlib.util,json,shutil

ROOT=Path(__file__).resolve().parents[1]
BASE='/mh-liver-pathways'
TUMORS={'hcc':'HCC','pcca':'pCCA','icca':'iCCA','crlm':'CRLM','pdac':'PDAC','pnet':'pNET','nelm':'NELM','ampullary':'Ampullary','chcca':'cHCC–CCA'}
SETTINGS={'first':'Initial advanced-disease treatment','biomarker':'Molecularly selected treatment','later':'Subsequent treatment','perioperative':'Around curative local treatment','combination':'Combination / sequencing evidence','transplant':'Transplant strategy'}

def build(src):
 spec=importlib.util.spec_from_file_location('matrix',src/'source/matrix_content.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
 refs=json.loads((src/'source/references.json').read_text())
 out=ROOT/'systemic';out.mkdir(exist_ok=True)
 def links(items):return ' · '.join(f'<a href="{esc(u)}" target="_blank" rel="noopener">{esc(t)}</a>' for t,u in items)
 def citation(pm):
  r=refs[pm]
  return f'<strong>{esc(r["trial"])}</strong> · {esc(r["author"])} · {esc(r["journal"])} · {esc(str(r["year"]))}<span class="source-access">PMID <a href="{r["pubmed"]}">{pm}</a> · DOI <a href="https://doi.org/{esc(r["doi"])}">{esc(r["doi"])}</a> · <a href="{esc(r["tmc"])}">TMC Library</a></span>'
 rows=''
 for setting,label in SETTINGS.items():
  cells=''
  for tumor in TUMORS:
   cards=[c for c in m.CARDS if c['setting']==setting and tumor in c['tumors']]
   content=''
   for c in cards:
    previews='<br>'.join(f'{esc(refs[pm]["trial"])} · {esc(refs[pm]["author"])} {refs[pm]["year"]} · PMID {pm}' for pm in c['refs'][:2])
    if not previews:previews='Guideline / protocol sources in detail'
    content+=f'<p><a href="#{c["id"]}">{esc(c["title"])}</a><small>{esc(c["position"])}</small><small>{previews}</small></p>'
   if not content:
    content={'perioperative':'No routine adjuvant systemic standard summarized for this setting.','transplant':'Review the disease-specific transplant pathway and competing nontransplant options.'}.get(setting,'Select by treatment history and tumor features; see detailed options below.')
    content=('No liver-transplant pathway is active for PDAC; continue the cancer-treatment roadmap.' if setting=='transplant' and tumor=='pdac' else 'No liver-transplant pathway is specified for ampullary cancer.' if setting=='transplant' and tumor=='ampullary' else content)
    content=f'<span class="empty-cell">{content}</span>'
   cells+=f'<td data-tumor="{tumor}">{content}</td>'
  rows+=f'<tr data-setting="{setting}"><th scope="row">{label}</th>{cells}</tr>'
 cards_html=''
 for c in m.CARDS:
  sources=''.join('<li>'+citation(pm)+'</li>' for pm in c['refs'])
  extra=('<p>'+links(c['links'])+'</p>') if c['links'] else ''
  cards_html+=f'''<article class="regimen-card" id="{c['id']}" data-tumors="{' '.join(c['tumors'])}" data-setting="{c['setting']}"><div class="section-top"><span class="eyebrow">{' / '.join(TUMORS[x] for x in c['tumors'])}</span><span class="badge">{esc(c['position'])}</span></div><h3>{esc(c['title'])}</h3><p><strong>When to consider.</strong> {esc(c['who'])}</p><p class="evidence-result"><strong>Clinical evidence.</strong> {esc(c['evidence'])}</p><p class="limits"><strong>Limits of the evidence.</strong> {esc(c['limits'])}</p><p><strong>Transplant implications.</strong> {esc(c['transplant'])}</p><details><summary>Trials and supporting sources ({len(c['refs'])+len(c['links'])})</summary><ul class="sources">{sources}</ul>{extra}</details></article>'''
 safety=''.join(f'<tr><th scope="row">{esc(t)}</th><td>{esc(a)}</td><td>{esc(b)}<p>{links(l)}</p></td></tr>' for t,a,b,l in m.SAFETY)
 guideline_html=''.join(f'<li><strong>{esc(t)}</strong> · <a href="{esc(u)}">{esc(n)}</a><br>{esc(p)}</li>' for t,n,p,u in m.GUIDELINES)
 library=''
 for pm,r in refs.items():
  ts=' '.join('pcca' if t=='hilar' else t for t in r['diseases'])
  library+=f'<article class="library-entry" data-tumors="{ts}" data-pdf="{("available" if r.get("pdf_file") else "needed")}"><p>{citation(pm)}</p><p class="paper-title">{esc(r["title"])}</p><small>{esc(r.get("pdf_status","Full PDF still needed"))}. Public links open the publisher, PubMed or TMC catalogue.</small></article>'
 count=sum(bool(r.get('pdf_file')) for r in refs.values())
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>Systemic therapy matrix | Memorial Hermann HPB Oncology</title><link rel="stylesheet" href="{BASE}/assets/evidence-tools.css"><link rel="stylesheet" href="{BASE}/assets/portal-navigation.css"><script src="{BASE}/assets/portal-navigation.js" defer></script><script src="matrix.js" defer></script></head><body><main class="evidence-wrap"><header class="tool-hero"><p class="eyebrow">Roadmaps / Treatment matrices</p><h1>Systemic therapy matrix</h1><p>Compare treatment settings across HPB tumor types, then open the clinical evidence, important limitations and transplant implications for each option.</p></header><div class="review-notice"><strong>Clinical review draft · Evidence reviewed through 25 October 2026.</strong> Choose by tumor type, stage, prior treatment, biomarkers, organ function and patient goals. Trial results retain their own populations and comparators; cross-trial survival medians do not rank treatments. This matrix supports multidisciplinary discussion and does not provide prescribing orders.</div><nav class="jump-links" aria-label="Page sections"><a href="#comparison">Compare treatments</a><a href="#options">Detailed options</a><a href="#safety">Contraindications and precautions</a><a href="#supportive">Best supportive care</a><a href="#library">Papers and PDF status</a></nav><nav class="tool-tabs" aria-label="Tumor filter"><button type="button" data-filter="all" aria-pressed="true">All HPB tumors</button>{''.join(f'<button type="button" data-filter="{k}" aria-pressed="false">{v}</button>' for k,v in TUMORS.items())}</nav><div class="matrix-toolbar"><label for="setting">Treatment setting</label><select id="setting"><option value="all">All settings</option>{''.join(f'<option value="{k}">{v}</option>' for k,v in SETTINGS.items())}</select><label for="therapy-search">Find a treatment or trial</label><input id="therapy-search" type="search" placeholder="FOLFOX, FGFR2, NETTER, immunotherapy…"><span id="result-count" aria-live="polite"></span></div><section id="comparison"><h2>At a glance</h2><p class="screen-note">On a phone, choose a tumor to narrow the matrix or scroll the table sideways. Select a treatment name for its evidence and limitations.</p><div class="matrix-scroll" tabindex="0" role="region" aria-label="Systemic therapy comparison"><table class="therapy-matrix"><thead><tr><th scope="col">Clinical setting</th>{''.join(f'<th scope="col" data-tumor="{k}">{v}</th>' for k,v in TUMORS.items())}</tr></thead><tbody>{rows}</tbody></table></div></section><section id="options"><h2>Treatment options and evidence</h2><p class="screen-note">OS = overall survival; PFS = progression-free survival; ORR = objective response rate; HR = hazard ratio; SSTR = somatostatin receptor; ICI = immune checkpoint inhibitor.</p><div class="regimen-grid">{cards_html}</div><p id="no-results" hidden>No matching option. Clear the search or select another tumor or setting.</p></section><section class="definition" id="molecular"><h2>Complete the molecular review</h2><p>For advanced biliary and colorectal cancers, obtain an adequate molecular profile early enough to affect treatment. Review MSI/MMR, relevant fusions and other actionable alterations using the disease-specific guideline and current drug indication. A rare alteration may support a tumor-agnostic therapy even when it is not represented by a separate card.</p><p>The October 2026 US pembrolizumab TMB-high indication uses <strong>≥13 mutations/Mb</strong>, an FDA-authorized test, prior progression and no satisfactory alternative. Older documents may retain ≥10; keep TMB-high selection separate from MSI-H/dMMR selection. <a href="https://www.fda.gov/drugs/resources-information-approved-drugs/fda-grants-traditional-approval-pembrolizumab-or-pembrolizumab-and-berahyaluronidase-alfa-pmph">FDA indication and evidence</a>.</p></section><section id="safety"><h2>Contraindications and major precautions</h2><p>Shared safety considerations across tumor types. Confirm the current product label, laboratory thresholds, interactions and perioperative timing for the selected regimen. An evidence gap in severe liver dysfunction is not equivalent to a formal label contraindication.</p><table class="safety-table"><thead><tr><th scope="col">Drug class</th><th scope="col">Reasons to avoid, delay or obtain specialist review</th><th scope="col">Practical implications and sources</th></tr></thead><tbody>{safety}</tbody></table></section><section id="supportive" class="definition"><h2>When further tumor-directed treatment is unsuitable</h2><p>Agree <strong>best supportive care</strong> with the patient and treating team. Treat pain, nausea, pruritus, ascites, obstruction, infection, malnutrition and other burdens; involve palliative care, and discuss hospice when appropriate. Palliative care can also accompany active anticancer treatment.</p><p>Reassess reversible causes of poor performance or organ function before concluding that further treatment is unsuitable. Record the agreed plan and a point of reassessment. <a href="https://www.cancer.gov/about-cancer/advanced-cancer/care-choices/palliative-care-fact-sheet">NCI · Palliative care</a>.</p><div class="button-row"><a href="../#hpb-roadmaps">Cancer roadmaps</a><a href="../lrt/">Liver-directed therapy matrix</a><a href="../transplant/high-risk/">High-risk transplant review</a></div></section><section id="guidelines"><h2>NCCN source editions and locations</h2><p>Page numbers below refer to the original PDF, including its front matter. Later FDA changes and newly published trials are identified separately above; these citations do not claim that the supplied editions are the latest available.</p><ul class="sources">{guideline_html}</ul></section><section id="library"><h2>Evidence library and PDF depot</h2><p>{len(refs)} indexed papers · {count} full PDFs verified in the local depot · {len(refs)-count} full PDFs still needed. This is a focused clinical evidence library, not a systematic review. A deposited PDF indicates verified identity and readable content; it does not mean every paper has undergone a complete critical appraisal.</p><p>Use <strong>TMC Library</strong>, then <strong>Available online / View online</strong> and UTHealth Houston sign-in. Licensed PDFs remain in the local depot.</p><div class="matrix-toolbar"><label for="paper-search">Search papers</label><input id="paper-search" type="search" placeholder="Trial, first author, journal, year or PMID"><label for="pdf-filter">PDF status</label><select id="pdf-filter"><option value="all">All papers</option><option value="needed">Full PDF still needed</option><option value="available">PDF in local depot</option></select><span id="paper-count" aria-live="polite"></span></div><div class="library-list">{library}</div></section><footer class="evidence-footer">Memorial Hermann / UTHealth Houston · HPB Oncology & Transplant Pathways · 25 October 2026 · Draft for multidisciplinary review.</footer></main></body></html>'''
 (out/'index.html').write_text(html)
 layout_spec=importlib.util.spec_from_file_location('systemic_disclosures',ROOT/'tools/systemic_disclosures.py')
 layout=importlib.util.module_from_spec(layout_spec);layout_spec.loader.exec_module(layout)
 layout.enhance(out/'index.html')
 public_refs={pm:{k:r.get(k,'') for k in ['pmid','title','trial','author','journal','year','doi','pubmed','tmc','diseases','pdf_status']} for pm,r in refs.items()}
 (out/'references.json').write_text(json.dumps(public_refs,ensure_ascii=False,indent=2))
 (out/'matrix.json').write_text(json.dumps({'review_date':'2026-10-25','cards':m.CARDS,'safety':m.SAFETY,'guidelines':m.GUIDELINES},ensure_ascii=False,indent=2))
 snapshot=ROOT/'tools/systemic_source';snapshot.mkdir(exist_ok=True);shutil.copyfile(src/'source/matrix_content.py',snapshot/'matrix_content.py')
 (out/'publication-manifest.json').write_text(json.dumps({'review_date':'2026-10-25','tumors':list(TUMORS),'treatment_cards':len(m.CARDS),'references':len(refs),'local_pdfs':count,'missing_pdfs':len(refs)-count,'licensed_pdfs_published':0,'status':'Clinical review draft'},indent=2))
 print(f'{len(m.CARDS)} treatment cards; {len(refs)} papers; {count} verified local PDFs.')

if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('source',type=Path);build(p.parse_args().source)
